tools.example:
# Inventory of the design
foreach c [get_bd_cells -hierarchical] {
  puts [format "%-32s %s" [get_property NAME $c] [get_property VLNV $c]]
}

# All AXI slave interfaces that are not yet connected
get_bd_intf_pins -filter {MODE == Slave && VLNV =~ *aximm*}

# Every clock pin of one cell
get_bd_pins -of_objects [get_bd_cells axi_dma_0] -filter {TYPE == clk}

# Address map audit
foreach s [get_bd_addr_segs] { puts "$s [get_property OFFSET $s] [get_property RANGE $s]" }
